// === Tab: mySketch ===
// UZUSHIO_2.0

let TATE = 100 ; let YOKO = 100 ; let H = 6 ; let Mmax = 10 ; 

let X[][] = new Array(YOKO)[TATE] ; let Y[][] = new Array(YOKO)[TATE] ;
let CX[] = new Array(Mmax) ; let CY[] = new Array(Mmax) ; 
let dX ; let dY ; let I ; let II ; let III ; let L ; let KX ; let KY ; let M ;



function setup(){

  createCanvas(600, 600) ; noSmooth() ; stroke(255) ; fill(255) ; 

  for ( I = 0 ; I < YOKO ; I++ ){
    for ( II = 0 ; II < TATE ; II++ ){
      X[I][II] = (I-(YOKO/2))*H ; Y[I][II] = (II-(TATE/2))*H ;  
    }
  }

} // setup()



function draw(){

  background(0) ;

  for ( I = 0 ; I < YOKO ; I++ ){
    for ( II = 0 ; II < TATE ; II++ ){
      KX = 125*cos(X[I][II]/20)+125 ; KY = 125*cos(Y[I][II]/20)+125 ; 
      fill(KX,0,KY) ; stroke(KX,0,KY) ; rect(I*H,II*H,H,H) ; 
      dX = 0 ; dY = 0 ; 
      for ( III = 0 ; III < M ; III++ ){
        KX = X[I][II]-CX[III] ; KY = Y[I][II]-CY[III] ;
        L = sqrt((KX*KX)+(KY*KY)) ;
        if ( int(III/2)*2 == III ){ dX = dX - ((-KX+KY)/pow(L,3)) ; dY = dY - ((-KX-KY)/pow(L,3)) ; }
                              else{ dX = dX + ((+KX+KY)/pow(L,3)) ; dY = dY - ((+KX-KY)/pow(L,3)) ; }
      }
      L = sqrt((dX*dX)+(dY*dY)) ;
      if ( L > 0 ){ dX = dX/L ; dY = dY/L ; } 
      X[I][II] = X[I][II] + dX ; Y[I][II] = Y[I][II] + dY ;
    }
  }

} // draw()



function mousePressed(){ 

  CX[M] = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-300 ; CY[M] = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-300 ;
  M = M + 1 ; if ( M >= Mmax ) { M = 0 ; }
  setup() ; 

}

